import sqlite3
from datetime import datetime, timezone
from langchain.tools import tool

DB_PATH = "/var/lib/logsvc/access.db"
VALID_ROLES = ("viewer", "editor", "admin")


def _write_audit(conn, app_name, user_email, role, granted_by):
    conn.execute(
        "INSERT INTO access_audit (app_name, user_email, role, granted_by, created_at) VALUES (?, ?, ?, ?, ?)",
        (app_name, user_email, role, granted_by, datetime.now(timezone.utc).isoformat()),
    )


@tool
def grant_log_dashboard_access(app_name: str, user_email: str, role: str, granted_by: str) -> str:
    if role not in VALID_ROLES:
        return f"Invalid role '{role}'. Choose from {', '.join(VALID_ROLES)}."
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT role FROM log_access WHERE app_name = ? AND user_email = ?",
            (app_name, user_email),
        ).fetchone()
        if row:
            conn.execute(
                "UPDATE log_access SET role = ? WHERE app_name = ? AND user_email = ?",
                (role, app_name, user_email),
            )
            previous = row[0]
        else:
            conn.execute(
                "INSERT INTO log_access (app_name, user_email, role) VALUES (?, ?, ?)",
                (app_name, user_email, role),
            )
            previous = None
        _write_audit(conn, app_name, user_email, role, granted_by)
        conn.commit()
    finally:
        conn.close()
    if previous:
        return f"Changed {user_email} on {app_name} from {previous} to {role}"
    return f"Granted {user_email} {role} access to {app_name}"

import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("log-admin")
DB_PATH = "/var/lib/logsvc/tokens.db"


@mcp.tool()
def revoke_log_ingest_token(app_name: str, token_id: str) -> str:
    if not app_name or not app_name.strip():
        return "Error: app_name is required."
    if not token_id or not token_id.strip():
        return "Error: token_id is required."
    if not token_id.startswith("ing_"):
        return "Error: token_id must start with 'ing_'."
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT app_name FROM ingest_tokens WHERE token_id = ?",
            (token_id,),
        ).fetchone()
        if row is None:
            return f"Error: token {token_id} not found."
        if row[0] != app_name:
            return f"Error: token {token_id} does not belong to {app_name}."
        conn.execute("DELETE FROM token_shares WHERE token_id = ?", (token_id,))
        conn.execute("DELETE FROM ingest_tokens WHERE token_id = ?", (token_id,))
        conn.commit()
    finally:
        conn.close()
    return f"Token {token_id} revoked for {app_name}."
